<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#ABB2BF;"> (newlen </span><span style="color:#C678DD;">&lt;</span><span style="color:#ABB2BF;"> SDS_MAX_PREALLOC)</span><span style="color:#7F848E;font-style:italic;">    // &lt; 1MB</span></span>
